insert into activation_results select 'RULE_CORRECTED',public.save_catalog_rule_draft((select(value->>'rule_id')::uuid from activation_results where kind='RULE'),v.id,jsonb_build_object('condition_ast',v.condition_ast,'actions',v.actions,'dependency_graph',v.dependency_graph,'priority',200,'sensitive',v.sensitive),'Correction après refus',3,3,'editorial206-rule-correct')from public.question_rule_versions v where v.id=(select(value->>'version_id')::uuid from activation_results where kind='RULE');
select ok(public.franchise_catalog_review_diff((select(value->>'franchise_id')::uuid from activation_results where kind='PROPOSE1'),(select(value->>'change_request_id')::uuid from activation_results where kind='RULE_SUB'))->'changes'@>'[{"field":"priority","before":100,"after":200}]'::jsonb,'corrected rule differs from immutable rejected source');
insert into activation_results values('RULE_RESUB',public.submit_franchise_catalog_rule((select(value->>'rule_id')::uuid from activation_results where kind='RULE_CORRECTED'),(select(value->>'version_id')::uuid from activation_results where kind='RULE_CORRECTED'),(select(value->>'identity_row_version')::int from activation_results where kind='RULE_CORRECTED'),(select(value->>'version_row_version')::int from activation_results where kind='RULE_CORRECTED'),'editorial206-rule-resubmit'));
reset role;select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
insert into activation_results values('RULE_APPROVED',public.decide_catalog_editorial_review((select(value->>'change_request_id')::uuid from activation_results where kind='RULE_RESUB'),'APPROVE','Décision motivée de recette',1,true,'editorial206-review-RULE_RESUB'));
select is((select value->>'targetType'from activation_results where kind='RULE_APPROVED'),'RULE','resubmitted standalone rule can be approved');
select is((public.catalog_editorial_review_detail((select(value->>'change_request_id')::uuid from activation_results where kind='RULE_SUB'))->'request'->>'reviewComment'),'Décision motivée de recette','rejected review reason stays available');
select ok((public.catalog_editorial_review_detail((select(value->>'change_request_id')::uuid from activation_results where kind='RULE_SUB'))->'reviewedSnapshot')is not null,'rejection keeps immutable source snapshot');
reset role;
select ok((select translation_review_status='APPROVED'and translation_reviewer_user_id='a2040000-0000-4000-8000-000000000002'from public.catalog_service_versions where id=(select(value->>'version_id')::uuid from activation_results where kind='SERVICE')),'service translation attestation names independent actual reviewer');
select is((select count(*)from public.catalog_editorial_review_snapshots where change_request_id=(select(value->>'change_request_id')::uuid from activation_results where kind='SERVICE_SUB')),1::bigint,'one immutable review despite retry');
select throws_ok($$update public.catalog_editorial_review_snapshots set reason='Nouvelle raison'where change_request_id=(select(value->>'change_request_id')::uuid from activation_results where kind='SERVICE_SUB')$$,'55000','IMMUTABLE_CATALOG_REVIEW_SNAPSHOT','review content cannot be rewritten');
select is((select count(*)from public.audit_events where action='catalog.editorial.review_recorded'and resource_id=(select(value->>'change_request_id')::uuid from activation_results where kind='SERVICE_SUB')::text),1::bigint,'review proof audit emitted once');
reset role;select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
insert into activation_results values('RELEASE',public.submit_franchise_catalog_publication('f2040000-0000-4000-8000-000000000001',(select row_version from public.catalog_libraries where id='f2040000-0000-4000-8000-000000000001'),'editorial206-release'));
select is((select value->>'status'from activation_results where kind='RELEASE'),'IN_REVIEW','sensitive publication requires central release approval');
reset role;insert into activation_results select'RELEASE_SUB',jsonb_build_object('change_request_id',id)from public.catalog_change_requests where target_type='RELEASE'and target_id=(select(value->>'release_id')::uuid from activation_results where kind='RELEASE');
reset role;select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
insert into activation_results values('RELEASE_DETAIL',public.catalog_editorial_review_detail((select(value->>'change_request_id')::uuid from activation_results where kind='RELEASE_SUB')));
select is((select jsonb_array_length(value->'releaseItems')from activation_results where kind='RELEASE_DETAIL'),5,'review includes exact frozen release manifest and children');
select ok((select not(value->'version'?'lease_token')from activation_results where kind='RELEASE_DETAIL'),'worker lease capability is never exposed');
insert into activation_results values('RELEASE_APPROVED',public.decide_catalog_editorial_review((select(value->>'change_request_id')::uuid from activation_results where kind='RELEASE_SUB'),'APPROVE','Décision motivée de recette',1,true,'editorial206-review-RELEASE_SUB'));
insert into activation_results values('RELEASE_CURRENT',public.catalog_editorial_review_detail((select(value->>'change_request_id')::uuid from activation_results where kind='RELEASE_SUB')));
select is((select value->'version'->>'status'from activation_results where kind='RELEASE_CURRENT'),'APPROVED','approval is distinct from scheduling or publication');
select throws_ok($$select public.schedule_reviewed_catalog_release((select(value->>'release_id')::uuid from activation_results where kind='RELEASE'),(select(value->>'releaseRowVersion')::int from activation_results where kind='RELEASE_CURRENT'),repeat('f',64),statement_timestamp()+interval'5 minutes',null,'editorial206-schedule')$$,'40001','STALE_CATALOG_VERSION','scheduling requires the reviewed release hash');
insert into activation_results values('SCHEDULE',public.schedule_reviewed_catalog_release((select(value->>'release_id')::uuid from activation_results where kind='RELEASE'),(select(value->>'releaseRowVersion')::int from activation_results where kind='RELEASE_CURRENT'),(select value->>'snapshotHash'from activation_results where kind='RELEASE_CURRENT'),statement_timestamp()+interval'5 minutes',null,'editorial206-schedule'));
select throws_ok($$select public.schedule_reviewed_catalog_release((select(value->>'release_id')::uuid from activation_results where kind='RELEASE'),null,(select value->>'snapshotHash'from activation_results where kind='RELEASE_CURRENT'),now(),null,'editorial206-null-cas')$$,'22023','INVALID_CATALOG_SCHEDULE','null scheduling version cannot bypass CAS');
select is((select value->>'outcome'from activation_results where kind='SCHEDULE'),'CATALOG_RELEASE_SCHEDULED','explicit command schedules publication through real existing command');
reset role;
select is((select status from public.catalog_releases where id=(select(value->>'release_id')::uuid from activation_results where kind='RELEASE')),'SCHEDULED','no false published status before worker execution');
select ok(not has_function_privilege('service_role','public.decide_catalog_editorial_review(uuid,text,text,integer,boolean,text,uuid)','execute'),'service role cannot impersonate human reviewer');
select ok(not has_function_privilege('authenticated','private.catalog_editorial_object(text,uuid,uuid,uuid,boolean)','execute'),'private full version reader is inaccessible directly');
reset role;select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
do $$declare n integer;created jsonb;begin for n in 1..30 loop
 created:=public.create_catalog_category('f2040000-0000-4000-8000-000000000001','EDITORIAL206_EXTRA_'||n,'editorial206-extra-'||n,'Catégorie '||n,'فئة '||n,'Description catégorie','وصف الفئة','category',n+10,'{}',false,'Création pagination','editorial206-extra-'||n);
 perform public.submit_catalog_change('CATEGORY',(created->>'category_id')::uuid,(created->>'version_id')::uuid,1,1,'editorial206-extra-submit-'||n);
end loop;end$$;
reset role;select set_config('request.jwt.claims','{"sub":"a2040000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
insert into activation_results values('PAGE1',public.catalog_editorial_review_queue(1,'CATEGORY')),('PAGE2',public.catalog_editorial_review_queue(2,'CATEGORY')),('PAGE3',public.catalog_editorial_review_queue(3,'CATEGORY'));
select is((select jsonb_array_length(value->'items')from activation_results where kind='PAGE1'),25,'queue first page is bounded to25');
select is((select jsonb_array_length(value->'items')from activation_results where kind='PAGE2'),5,'queue second page reaches records beyond25');
select is((select jsonb_array_length(value->'items')from activation_results where kind='PAGE3'),0,'empty page after complete queue is honest');
select is((select count(distinct item->>'id')from activation_results cross join lateral jsonb_array_elements(value->'items')item where kind in('PAGE1','PAGE2')),30::bigint,'stable pages contain no duplicates or omissions');
reset role;
select *from finish();rollback;
